  [("asombro", "sorpresa que nace cuando algo obvio deja de serlo y nos lleva a preguntar"), ("rutina", "forma de hacer o ver las cosas por costumbre, sin preguntar"), ("duda", "no estar seguro de algo y preguntarse si se sostiene"), ("dar por sentado", "aceptar algo como obvio sin examinarlo")],
  [("Reconocer asombro", "De la ficha: ¿R1 muestra asombro filosófico?", ["Camila se detiene ante algo que daba por obvio: «el mismo bus».", "Pasa de la costumbre a una pregunta sobre qué es «lo mismo»."], "Sí, muestra asombro"),
   ("Reconocer rutina", "De la ficha: ¿R3 muestra asombro filosófico o una comprobación de rutina?", ["La trabajadora solo verifica una suma.", "No se cuestiona ningún concepto."], "Una comprobación de rutina")],
